/**
 * Generated by `createschema ai.AISkill 'name:Text; description:Text; displayName?:Text; displayDescription?:Text; content:Text; license?:Text; compatibility?:Text; metadata?:Json; allowedTools?:Text; locale:Select:ru,en,es; meta?:Json; isPublic:Checkbox; image?:File; examples?:Json; b2bApp?:Relationship:B2BApp:SET_NULL; scope:Select:global,organization,personal,b2bApp; organization?:Relationship:Organization:SET_NULL; user?:Relationship:User:SET_NULL;' --force`
 */

const { historical, versioned, uuided, tracked, softDeleted, dvAndSender, analytical } = require('@open-condo/keystone/plugins')
const { GQLListSchema } = require('@open-condo/keystone/schema')

const access = require('@condo/domains/ai/access/AISkill')
const { LOGO_FIELD } = require('@condo/domains/miniapp/schema/fields/integration')
const { LOCALES } = require('@condo/domains/user/constants/common')


const SKILL_NAME_REGEX = /^[a-z0-9]+(-[a-z0-9]+)*$/
const SKILL_NAME_MAX_LENGTH = 64
const SKILL_DESCRIPTION_MAX_LENGTH = 1024
const SKILL_COMPATIBILITY_MAX_LENGTH = 500
const SCOPE_RELATION_FIELDS = ['organization', 'user', 'b2bApp']
const SCOPE_REQUIRED_RELATION_FIELDS = {
    organization: 'organization',
    personal: 'user',
    b2bApp: 'b2bApp',
}

function validateAgentSkillFields (skill, addValidationError) {
    if (!skill.name || !SKILL_NAME_REGEX.test(skill.name)) {
        addValidationError('Skill name must contain only lowercase letters, numbers, and hyphens. Must not start or end with a hyphen.')
    }
    if (skill.name && skill.name.length > SKILL_NAME_MAX_LENGTH) {
        addValidationError(`Skill name must be at most ${SKILL_NAME_MAX_LENGTH} characters`)
    }
    if (!skill.description || !skill.description.trim()) {
        addValidationError('Skill description must not be empty')
    }
    if (skill.description && skill.description.length > SKILL_DESCRIPTION_MAX_LENGTH) {
        addValidationError(`Skill description must be at most ${SKILL_DESCRIPTION_MAX_LENGTH} characters`)
    }
    if (!skill.content || !skill.content.trim()) {
        addValidationError('Skill content must not be empty')
    }
    if (skill.compatibility && skill.compatibility.length > SKILL_COMPATIBILITY_MAX_LENGTH) {
        addValidationError(`Skill compatibility must be at most ${SKILL_COMPATIBILITY_MAX_LENGTH} characters`)
    }
    if (skill.examples != null && (!Array.isArray(skill.examples) || !skill.examples.every(example => typeof example === 'string'))) {
        addValidationError('Examples must be an array of strings')
    }
}

function validateScopeRelations (skill, addValidationError) {
    const requiredField = SCOPE_REQUIRED_RELATION_FIELDS[skill.scope]
    if (requiredField && !skill[requiredField]) {
        addValidationError(`${requiredField} must be set when scope is "${skill.scope}"`)
    }

    const unexpectedFields = SCOPE_RELATION_FIELDS.filter(field => field !== requiredField && skill[field])
    if (unexpectedFields.length) {
        addValidationError(`${unexpectedFields.join(', ')} must not be set when scope is "${skill.scope}"`)
    }
}

/**
 * @deprecated This model is experimental – its API might change in the future.
 * Use at your own risk
 */
const AISkill = new GQLListSchema('AISkill', {
    schemaDoc: 'Warning: This model is experimental – its API might change in the future. AI assistant skill in agentskills (https://agentskills.io/specification) format. Can be provided by a B2BApp (miniapp) or created by users. Used by the AI assistant',
    fields: {

        // Below is API from https://agentskills.io/specification

        name: {
            schemaDoc: 'Agent Skills spec name; lowercase slug, max 64 characters.',
            type: 'Text',
            isRequired: true,
        },

        description: {
            schemaDoc: 'Agent Skills spec description; usage summary, max 1024 characters.',
            type: 'Text',
            isRequired: true,
        },

        content: {
            schemaDoc: 'Agent Skills specification Markdown body containing AI instructions.',
            type: 'Text',
            isRequired: true,
        },

        license: {
            schemaDoc: 'Optional Agent Skills specification license or bundled license file.',
            type: 'Text',
        },

        compatibility: {
            schemaDoc: 'Agent Skills spec compatibility; optional, max 500 characters.',
            type: 'Text',
        },

        metadata: {
            schemaDoc: 'Optional Agent Skills specification key-value metadata.',
            type: 'Json',
        },

        allowedTools: {
            schemaDoc: 'Agent Skills spec allowed-tools; optional and experimental.',
            type: 'Text',
        },

        // Other fields
        
        locale: {
            schemaDoc: 'Locale of the user-facing skill fields.',
            type: 'Select',
            options: LOCALES,
            isRequired: true,
        },

        isPublic: {
            schemaDoc: 'If true – users can see and invoke the skill.',
            type: 'Checkbox',
            isRequired: true,
            defaultValue: false,
        },

        scope: {
            schemaDoc: 'Availability: global, organization, personal, or connected B2BApp.',
            type: 'Select',
            options: 'global,organization,personal,b2bApp',
            isRequired: true,
            defaultValue: 'global',
        },

        displayName: {
            schemaDoc: 'Optional user-facing skill name shown in the interface.',
            type: 'Text',
        },

        displayDescription: {
            schemaDoc: 'Optional user-facing skill description shown in the interface.',
            type: 'Text',
        },

        meta: {
            schemaDoc: 'Additional arbitrary data about the skill.',
            type: 'Json',
        },

        image: {
            ...LOGO_FIELD,
            schemaDoc: 'Skill illustration image. Shown on skill cards and detail view.',
        },

        examples: {
            schemaDoc: 'Array of example prompt strings',
            type: 'Json',
            graphQLInputType: '[String!]',
            graphQLReturnType: '[String!]',
        },

        organization: {
            schemaDoc: 'Organization for org-scoped skills. Required when scope=organization.',
            type: 'Relationship',
            ref: 'Organization',
            kmigratorOptions: { null: true, on_delete: 'models.SET_NULL' },
        },

        user: {
            schemaDoc: 'User for personal skills. Required when scope=personal. Might differ from createdBy',
            type: 'Relationship',
            ref: 'User',
            kmigratorOptions: { null: true, on_delete: 'models.SET_NULL' },
        },

        b2bApp: {
            schemaDoc: 'B2BApp which created this skill.',
            type: 'Relationship',
            ref: 'B2BApp',
            kmigratorOptions: { null: true, on_delete: 'models.SET_NULL' },
        },

    },
    hooks: {
        validateInput: ({ resolvedData, existingItem, addValidationError }) => {
            const skill = { ...existingItem, ...resolvedData }

            validateAgentSkillFields(skill, addValidationError)
            validateScopeRelations(skill, addValidationError)
        },
    },
    plugins: [uuided(), versioned(), tracked(), softDeleted(), dvAndSender(), historical(), analytical()],
    access: {
        read: access.canReadAISkills,
        create: access.canManageAISkills,
        update: access.canManageAISkills,
        delete: false,
    },
})

module.exports = {
    AISkill,
}
